UPDATE courses SET
    course_description = '<h4>Overview</h4> <p> This postgraduate research degree provides an opportunity for graduates to develop their research skills, to deepen their knowledge in an selected area of study and to undertake some original, independent research. Students are supported throughout the degree by a supervisor(s) and panel of academic and industry collaborators. The degree provides students with the experience and expert knowledge needed to confidently approach PhD studies or a research career in a chosen field. </p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = 89285,
    onshore_tuition_fee = 87751,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<table><tbody><tr><td><strong>Academic Requirements</strong></td><td> <p>Applicants must have completed a UTS recognised bachelor''s degree, or an equivalent or higher qualification, or submitted other evidence of general and professional qualifications that demonstrates potential to pursue graduate research studies.</p><p>Eligibility for admission does not guarantee offer of a place.</p><strong>English language requirements</strong><p>IELTS Academic: overall 6.5, writing 6.0 TOEFL iBT: overall 79, writing 21 UTS College AE5: Pass Pearson PTE: overall 58, writing 50 Cambridge C1A/C2P: overall 176, writing 169</p> </td></tr><tr><td><strong>English Proficiency</strong></td><td><ul><li>IELTS (Academic) score: 6.5 overall with a writing score of 6.0 (or equivalent).</li></ul></td></tr></tbody></table>',
    apply_form = 'https://www.uts.edu.au/courses/master-of-transdisciplinary-innovation-research',
    updated_at = NOW()
